class MinStack:
    def __init__(self):
        # Initialize two stacks, one for storing all values and another for keeping track of min values
        self.stack = []
        self.min_stack = []

    def push(self, val: int) -> None:
        # Push the value onto the main stack
        self.stack.append(val)
        # Push the value onto the min stack if it's smaller than or equal to the current minimum
        if not self.min_stack or val <= self.min_stack[-1]:
            self.min_stack.append(val)

    def pop(self) -> None:
        # Pop the value from the main stack
        val = self.stack.pop()
        # If the popped value is the current minimum, also pop it from the min stack
        if val == self.min_stack[-1]:
            self.min_stack.pop()

    def top(self) -> int:
        # Return the top value of the main stack
        return self.stack[-1]

    def get_min(self) -> int:
        # Return the current minimum value from the min stack
        return self.min_stack[-1]
